/**
 * Mirror composites for eye closure (FPA-GEOM 0.5.0).
 *
 * With only one eye closed the landmark model reads the closed eye 25–32 % short: it pulls the face towards symmetry,
 * and tracking cannot help because a closing lid covers the iris and the lid points leave the tracking trust. Here the
 * half of the face holding one eye is mirrored across the facial midline, so the model sees a symmetric face with that
 * eye on both sides and nothing to pull towards. Bench (real faces, one eye closed by half synthesis): the closed eye
 * keeps 100 % of its value (tracking 68–75 %), the still eye reads ≈ 0.
 *
 * Works on the tracker's reference-aligned face crops (gray), so rest and expression composites share one midline.
 */
import { SIDE, type FrameObservation, type Side, type Vec2 } from '../core';
import { MIDLINE } from '../core/landmarks';
import type { Gray, TrackRef } from './track';

export type Detect = (src: HTMLCanvasElement) => Promise<FrameObservation>;

export interface EyeClosure {
  left: number | null;
  right: number | null;
}

/** Gray image → canvas (R = G = B) for the landmarker. */
export function grayCanvas(g: Gray): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = g.w;
  c.height = g.h;
  const ctx = c.getContext('2d')!;
  const img = ctx.createImageData(g.w, g.h);
  for (let i = 0; i < g.w * g.h; i++) {
    const v = g.data[i]!;
    img.data[4 * i] = v;
    img.data[4 * i + 1] = v;
    img.data[4 * i + 2] = v;
    img.data[4 * i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  return c;
}

/** Facial midline x = a·y + b fitted on the nose-bridge-to-tip landmarks. */
export function midline(pts: readonly Vec2[]): { a: number; b: number } {
  const p = MIDLINE.map((i) => pts[i]!);
  const my = p.reduce((s, q) => s + q.y, 0) / p.length;
  const mx = p.reduce((s, q) => s + q.x, 0) / p.length;
  let sxy = 0;
  let syy = 0;
  for (const q of p) {
    sxy += (q.y - my) * (q.x - mx);
    syy += (q.y - my) ** 2;
  }
  const a = syy > 0 ? sxy / syy : 0;
  return { a, b: mx - a * my };
}

/** The half of `src` holding `keep`, with the other half replaced by its reflection across the midline. */
export function mirrorComposite(src: HTMLCanvasElement, line: { a: number; b: number }, keep: Vec2): HTMLCanvasElement {
  const W = src.width;
  const H = src.height;
  const c = document.createElement('canvas');
  c.width = W;
  c.height = H;
  const g = c.getContext('2d')!;
  g.drawImage(src, 0, 0);
  const xAt = (y: number) => line.a * y + line.b;
  const side = Math.sign(keep.x - xAt(keep.y)) || 1;
  const far = side > 0 ? -10 * W : 11 * W;
  g.save();
  g.beginPath();
  g.moveTo(xAt(-H), -H);
  g.lineTo(xAt(2 * H), 2 * H);
  g.lineTo(far, 2 * H);
  g.lineTo(far, -H);
  g.closePath();
  g.clip();
  // Reflection across the line: through p0, tilted by beta from the vertical.
  const y0 = H / 2;
  const p0 = { x: xAt(y0), y: y0 };
  const beta = Math.atan(line.a);
  g.translate(p0.x, p0.y);
  g.rotate(-beta);
  g.scale(-1, 1);
  g.rotate(beta);
  g.translate(-p0.x, -p0.y);
  g.drawImage(src, 0, 0);
  g.restore();
  return c;
}

/** Mean lid-pair distance of both eyes (pixels); in a composite both are the same eye. */
function apertureBoth(o: FrameObservation): number | null {
  if (o.landmarks.length < 468 * 3) return null;
  const px = (i: number) => ({ x: o.landmarks[3 * i]! * o.width, y: o.landmarks[3 * i + 1]! * o.height });
  let s = 0;
  let n = 0;
  for (const side of ['left', 'right'] as const)
    for (const [u, l] of SIDE[side].lidPairs) {
      const A = px(u);
      const B = px(l);
      s += Math.hypot(A.x - B.x, A.y - B.y);
      n++;
    }
  return s / n;
}

/** Reference landmarks in crop pixels. */
function refPoints(ref: TrackRef): Vec2[] {
  const { obs, crop } = ref;
  const out: Vec2[] = [];
  for (let i = 0; i < 468; i++)
    out.push({
      x: crop.scale * (obs.landmarks[3 * i]! * obs.width - crop.x),
      y: crop.scale * (obs.landmarks[3 * i + 1]! * obs.height - crop.y),
    });
  return out;
}

const eyeCenter = (pts: readonly Vec2[], side: Side): Vec2 => {
  const a = pts[SIDE[side].eyeOuter]!;
  const b = pts[SIDE[side].eyeInner]!;
  return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
};

/**
 * Closure fraction of each eye (1 − aperture / rest aperture) on its own mirror composite, for frames drawn into the
 * reference crop. `need(i)` limits the work to frames that need it (null result for the others).
 */
export async function mirrorClosures(
  ref: TrackRef,
  restGray: Gray,
  frames: readonly Gray[],
  detect: Detect,
  need: (i: number) => boolean = () => true,
): Promise<(EyeClosure | null)[]> {
  const pts = refPoints(ref);
  const line = midline(pts);
  const keep = { left: eyeCenter(pts, 'left'), right: eyeCenter(pts, 'right') };
  const rest = grayCanvas(restGray);
  const restAp: Partial<Record<Side, number | null>> = {};
  for (const side of ['left', 'right'] as const) restAp[side] = apertureBoth(await detect(mirrorComposite(rest, line, keep[side])));
  const out: (EyeClosure | null)[] = [];
  for (const [i, g] of frames.entries()) {
    if (!need(i)) {
      out.push(null);
      continue;
    }
    const src = grayCanvas(g);
    const res: EyeClosure = { left: null, right: null };
    for (const side of ['left', 'right'] as const) {
      const r = restAp[side];
      if (!r) continue;
      const e = apertureBoth(await detect(mirrorComposite(src, line, keep[side])));
      if (e !== null) res[side] = Math.min(1, Math.max(0, 1 - e / r));
    }
    out.push(res);
  }
  return out;
}
