/**
 * Landmark tracking for captures (video assessment, photo set, bench): one rest frame is the
 * reference; every later frame is drawn into the reference's face crop with the head motion undone,
 * and the reference landmarks are tracked into it (see track.ts for why detection alone is not enough).
 */
import {
  LID_TRACKED_MIN,
  SIDE,
  buildRestReference,
  measureLive,
  taskSignal,
  type FrameObservation,
  type MovementTaskId,
  type TaskId,
} from '../core';
import { mirrorClosures, type Detect } from './mirror';
import { cropFor, cropTransform, pyramid, toRef, trackAligned, type Gray, type TrackRef } from './track';

const LIDS = { left: SIDE.left.lidPairs.flat(), right: SIDE.right.lidPairs.flat() };

export interface Grabbed {
  obs: FrameObservation;
  gray: Gray;
}

const hasFace = (o: FrameObservation) => o.landmarks.length >= 468 * 3;

export class CaptureTracker {
  ref: TrackRef | null = null;
  /** Mean share of points kept by the last `track` call (for logs and the bench). */
  lastKept = 0;
  private canvas: HTMLCanvasElement | null = null;
  /** Frames picked per task (gray crops with their tracked observations), for the eye-closure mirror step. */
  private picked = new Map<string, { grays: Gray[]; obs: FrameObservation[] }>();

  reset(): void {
    this.ref = null;
    this.picked.clear();
  }

  /** Makes `obs` (a valid rest frame of `src`) the reference. */
  setRef(src: CanvasImageSource, obs: FrameObservation): void {
    if (!hasFace(obs)) return;
    const crop = cropFor(obs);
    const gray = this.draw(src, crop.w, crop.h, cropTransform(crop, { s: 1, c: 1, sn: 0, tx: 0, ty: 0 }));
    this.ref = gray ? { obs, crop, pyr: pyramid(gray, 3), gray } : null;
  }

  /** The frame drawn into the reference crop (null without a reference or a face). */
  grab(src: CanvasImageSource, obs: FrameObservation): Gray | null {
    if (!this.ref || !hasFace(obs)) return null;
    const { crop } = this.ref;
    return this.draw(src, crop.w, crop.h, cropTransform(crop, toRef(this.ref.obs, obs)));
  }

  /** One frame tracked from the reference (the detection itself if tracking is not possible), with its lid-point share. */
  track(g: Grabbed): FrameObservation {
    if (!this.ref) return g.obs;
    const st: { kept: number; lost?: number[] } = { kept: 0 };
    const out = trackAligned(this.ref, g.obs, pyramid(g.gray, 3), undefined, st);
    this.lastKept = st.kept;
    const lost = new Set(st.lost ?? []);
    const share = (ids: number[]) => ids.filter((i) => !lost.has(i)).length / ids.length;
    return { ...out, lidTracked: { left: share(LIDS.left), right: share(LIDS.right) } };
  }

  /**
   * Eye-closure mirror step (FPA-GEOM 0.5.0) for the frames picked for `key`: frames where an eye's lid points were
   * not tracked get `mirrorClosure` (in place, on the observations already handed out). Run with the camera stopped:
   * `detect` switches the landmarker to image mode.
   */
  async addMirror(key: string, detect: Detect): Promise<number> {
    const p = this.picked.get(key);
    if (!this.ref?.gray || !p) return 0;
    const need = (i: number) => {
      const t = p.obs[i]?.lidTracked;
      return !!t && Math.min(t.left, t.right) < LID_TRACKED_MIN;
    };
    const res = await mirrorClosures(this.ref, this.ref.gray, p.grays, detect, need);
    let n = 0;
    res.forEach((r, i) => {
      if (r && p.obs[i]) {
        p.obs[i]!.mirrorClosure = r;
        n++;
      }
    });
    return n;
  }

  /**
   * Frames for the analysis of one recorded task: the ≤ maxN frames the analysis would pick
   * (strongest movement by the detection, rest: evenly spread), tracked from the reference.
   * Without a reference or grabbed frames the detections are returned unchanged.
   */
  trackTask(task: TaskId, frames: readonly FrameObservation[], grabbed: readonly Grabbed[], maxN = 12): FrameObservation[] {
    if (!this.ref || grabbed.length === 0) return [...frames];
    if (task === 'rest') return [this.ref.obs, ...this.trackEven(frames, grabbed, maxN)];
    let pick: Grabbed[];
    {
      const restRef = buildRestReference([this.ref.obs, this.ref.obs, this.ref.obs]);
      if (!restRef) return [...frames];
      pick = grabbed
        .map((g) => {
          const v = measureLive(task as MovementTaskId, restRef, g.obs);
          return { g, s: v ? taskSignal(v) : -Infinity };
        })
        .filter((x) => x.s > -Infinity)
        .sort((a, b) => b.s - a.s)
        .slice(0, maxN)
        .map((x) => x.g);
    }
    const out = this.trackAll(pick);
    this.picked.set(task, { grays: pick.map((g) => g.gray), obs: out });
    return out;
  }

  /**
   * ≤ maxN frames spread evenly over a recording (the rise and the hold alike: the synkinesis finder
   * correlates regions over time), tracked from the reference. Detections without a reference.
   */
  trackEven(frames: readonly FrameObservation[], grabbed: readonly Grabbed[], maxN = 16, key?: string): FrameObservation[] {
    if (!this.ref || grabbed.length === 0) return [...frames];
    const step = Math.max(1, grabbed.length / maxN);
    const pick = Array.from({ length: Math.min(maxN, grabbed.length) }, (_, k) => grabbed[Math.floor(k * step)]!);
    const out = this.trackAll(pick);
    if (key) this.picked.set(key, { grays: pick.map((g) => g.gray), obs: out });
    return out;
  }

  private trackAll(pick: readonly Grabbed[]): FrameObservation[] {
    let kept = 0;
    const out = pick.map((g) => {
      const o = this.track(g);
      kept += this.lastKept;
      return o;
    });
    this.lastKept = pick.length ? kept / pick.length : 0;
    return out;
  }

  private draw(src: CanvasImageSource, w: number, h: number, t: [number, number, number, number, number, number]): Gray | null {
    const c = (this.canvas ??= document.createElement('canvas'));
    if (c.width !== w) c.width = w;
    if (c.height !== h) c.height = h;
    const ctx = c.getContext('2d', { willReadFrequently: true });
    if (!ctx) return null;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, w, h);
    ctx.setTransform(...t);
    ctx.drawImage(src, 0, 0);
    const d = ctx.getImageData(0, 0, w, h).data;
    const data = new Uint8Array(w * h);
    for (let i = 0; i < w * h; i++) data[i] = (77 * d[4 * i]! + 150 * d[4 * i + 1]! + 29 * d[4 * i + 2]!) >> 8;
    return { w, h, data };
  }
}
